      pt: ["Abriga o Templo do Buda de Esmeralda (Wat Phra Kaew).", "A construção começou sob o rei Rama I.", "Consiste em numerosos edifícios, salões e pavilhões."],
      fr: ["Abrite le temple du Bouddha d'émeraude (Wat Phra Kaew).", "La construction a commencé sous le roi Rama I.", "Se compose de nombreux bâtiments, salles et pavillons."],
