        pt: "Um templo budista sagrado no monte Doi Suthep, perto de Chiang Mai. É um importante local de peregrinação para budistas devotos.",
        fr: "Un temple bouddhiste sacré sur le mont Doi Suthep près de Chiang Mai. C'est un lieu de pèlerinage important pour les bouddhistes dévots.",
